@startuml

class Customer {
  +name : string
  +address : string
}

class Account {
  +balance : double
}

class SavingAccount extends Account {
  +interestRate : float
}

class InvestmentAccount extends Account {
}

class Stock {
  +ticker : string
}

class StockOrder {
  +quantity : int
  +price : double
  +commission : float
}

Customer "1" -- "*" Account
SavingAccount -- "0..*" StockOrder
InvestmentAccount -- "0..*" StockOrder
StockOrder --> "1" Stock

@enduml

